-- Wires up the C++ scripts in src/server/scripts/Spells/spell_mage.cpp (spell_mage_frostbolt_icicles,
-- spell_mage_frostfire_bolt_icicles, spell_mage_blizzard_icicles, spell_mage_glacial_spike,
-- spell_mage_flurry, spell_mage_refreshment, spell_mage_frozen_orb, spell_mage_frozen_orb_pulse).
-- Frostbolt/Frostfire Bolt/Blizzard already carry other, unrelated scripts - spell_script_names
-- supports multiple rows per spell_id (its unique key is (spell_id, ScriptName)), so these add
-- to, rather than replace, whatever's already registered for those three IDs.
DELETE FROM `spell_script_names` WHERE (`spell_id`, `ScriptName`) IN ((116, 'spell_mage_frostbolt_icicles'), (44614, 'spell_mage_frostfire_bolt_icicles'), (10, 'spell_mage_blizzard_icicles'), (200002, 'spell_mage_glacial_spike'), (200004, 'spell_mage_flurry'), (200006, 'spell_mage_refreshment'), (200007, 'spell_mage_frozen_orb'), (200008, 'spell_mage_frozen_orb_pulse'));
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(116, 'spell_mage_frostbolt_icicles'),
(44614, 'spell_mage_frostfire_bolt_icicles'),
(10, 'spell_mage_blizzard_icicles'),
(200002, 'spell_mage_glacial_spike'),
(200004, 'spell_mage_flurry'),
(200006, 'spell_mage_refreshment'),
(200007, 'spell_mage_frozen_orb'),
(200008, 'spell_mage_frozen_orb_pulse');

-- Conjure Mana Gem's conjured item (5514, Mana Agate): repointed spellid_2 from the old flat
-- "Replenish Mana" (5405, base_points=389) to the new SPELL_EFFECT_ENERGIZE_PCT spell (200005,
-- 30% of max mana - docs/frost-mage-redesign.md sec 2). Plain UPDATE, not DELETE+INSERT -
-- item_template is on this repo's SQL linter's do-not-delete list (creature/gameobject/item/quest
-- templates - deleting one can orphan a live item), and a single-column UPDATE is the more precise
-- edit anyway. The `spellid_2 = 5405` guard makes it a no-op on a second run. 5405 itself is
-- untouched - it's shared with two unrelated items (36799 "Mana Gem", 9397 "Energy Cloak") that
-- should keep the old flat behavior.
UPDATE `item_template` SET `spellid_2` = 200005 WHERE `entry` = 5514 AND `spellid_2` = 5405;

-- Conjure Refreshment's item (43518, Conjured Mana Pie): repointed spellid_1 from the real pulled
-- flat-value wrapper (61828 "Refreshment", chaining 61829 "Food"/61830 "Drink") to the new
-- percentage-based spell (200006 - docs/frost-mage-redesign.md sec 2, "100% of max health and
-- 100% of max mana over 30 sec"). See mage.csv's notes on 200006 and spell_mage_refreshment
-- (spell_mage.cpp) for why this needed a real AuraScript rather than a data-only edit. Plain
-- UPDATE, not DELETE+INSERT, same reasoning as the Mana Agate edit above. 61828/61829/61830
-- themselves are untouched - they're real pulled spells, not owned by this ticket, and nothing
-- else in this branch points at them.
UPDATE `item_template` SET `spellid_1` = 200006 WHERE `entry` = 43518 AND `spellid_1` = 61828;

-- Conjure Food (587) / Conjure Water (5504) retirement in favor of Conjure Refreshment
-- (docs/frost-mage-redesign.md sec 2). The single-rank conversion already purged every superseded
-- rank's trainer_spell row (verified live: only these two survivor IDs still have any); dropping
-- these last two rows makes them fully untrainable. Deliberately not deleting the spell_dbc/item
-- data itself - existing characters who already know them, or anything else that still references
-- the IDs, keep working; they just stop being taught.
DELETE FROM `trainer_spell` WHERE (`TrainerId`, `SpellId`) IN ((16, 587), (17, 587), (16, 5504), (17, 5504));

-- Deep Freeze (44572, moved from npc.csv to mage.csv - see its notes there) needs to actually be
-- reachable now that it's leaving the old Talent.dbc row (docs/frost-mage-redesign.md sec 2:
-- "Learn level: 42"). No pre-existing trainer_spell row for it (spell was talent-only before) - the
-- DELETE here is only for idempotency on a second run, same as every other INSERT in this file. Its
-- own numbers (30s cooldown, 5s stun, frozen-only usability) already match the spec as-is; see
-- mage.csv's notes on the two real gaps that remain (both C++, not data).
DELETE FROM `trainer_spell` WHERE (`TrainerId`, `SpellId`) IN ((16, 44572), (17, 44572));
INSERT INTO `trainer_spell` (`TrainerId`, `SpellId`, `MoneyCost`, `ReqSkillLine`, `ReqSkillRank`, `ReqAbility1`, `ReqAbility2`, `ReqAbility3`, `ReqLevel`, `VerifiedBuild`) VALUES
(16, 44572, 20000, 0, 0, 0, 0, 0, 42, 0),
(17, 44572, 20000, 0, 0, 0, 0, 0, 42, 0);

-- Frozen Orb's projectile (300001, npc_mage_frozen_orb in spell_mage.cpp) - the invisible-stalker
-- trigger creature summoned by spell 200007. Not pulled/generated data (this table isn't part of
-- dbc-tools' pipeline), hand-authored off the real 'Invisible Stalker' template (entry 15214):
-- unit_flags = NOT_SELECTABLE | IMMUNE_TO_PC | IMMUNE_TO_NPC (33555200, the same combo the real
-- "Dark Assault Portal - Invisible Stalker" rows already use), flags_extra = TRIGGER | CIVILIAN |
-- NO_XP (194). faction=35 (friendly-to-everyone) is only the spawn default - IsSummonedBy
-- immediately overrides it to the owner's faction (the faction-35 trap the implementation plan
-- warns about: left on 35, the orb's own TARGET_UNIT_SRC_AREA_ENEMY pulse cast would find zero
-- targets). AIName left blank; ScriptName='npc_mage_frozen_orb' is what RegisterCreatureAI wires
-- up. Display (1126, the same stock invisible-stalker model 15214 itself uses) is a functional
-- placeholder, not the real "glowing orb" model - see mage.csv's notes on 200007 for why picking
-- one is deferred to an art pass rather than guessed here.
-- No DELETE here - creature_template is on this repo's SQL linter's do-not-delete list (same
-- reasoning as the item_template edits above), and unlike those this is a first-time INSERT, not
-- an edit to an existing row, so there's no matching UPDATE...WHERE to fall back on either. An
-- upsert is both idempotent and never deletes.
