-- ---------------------------------------------------------------
-- originally rev_1787609898874727299.sql
-- ---------------------------------------------------------------
-- Frost Mage rework - talent tree content, new-C++ pass, Cluster A (docs/frost-mage-talent-tree-content-handoff.md
-- "Next up: Step 3 game plan", Cluster A): Frostbite (38, spells 11071/12496/12497, freeze spell 12494).
--
-- Freezing itself and breaking on damage both turned out to be free from native data, not new C++:
-- 12494's Frost-school MOD_ROOT effect already satisfies SpellInfo::GetAuraState's generic "Frost
-- school + stun/root effect -> AURA_STATE_FROZEN" check (the same mechanism Frost Nova's own root
-- relies on), so Shatter/Ice Lance/Deep Freeze's usability gate all recognize it with zero extra
-- wiring; added AuraInterruptFlags = 524290 (AURA_INTERRUPT_FLAG_TAKE_DAMAGE | ...CHANGE_MAP, the
-- same combination Polymorph already uses) so it now breaks on any damage too.
--
-- The proc itself did need a real change: the pulled data used SPELL_AURA_ADD_TARGET_TRIGGER (109)
-- scoped by EffectSpellClassMaskA to a handful of named "chill" spells (matching the old tooltip,
-- "Gives your Chill effects a chance..."), which (a) doesn't match the redesign's broader "Dealing
-- direct Frost damage" wording and (b) can never reach a no-SpellFamilyFlags scripted trigger spell
-- like Frozen Orb - the same classmask-reachability hole Chilled to the Bone hit last pass. Converted
-- to a plain SPELL_AURA_PROC_TRIGGER_SPELL (42, no classmask - EffectSpellClassMaskA_1 dropped),
-- ProcChance set to the literal 5/10/15 (Brain Freeze/Biting Cold's convention, not the old
-- EffectBasePoints-sentinel one), AttributesEx3/ProcTypeMask copied from Brain Freeze/Biting Cold
-- ("direct spell damage dealt"); the actual Frost-school restriction now lives in
-- spell_mage_frostbite::CheckProc (same commit) rather than in a classmask, so Frozen Orb reaches it.
--
-- Rank 3 (12497) additionally carries the Mastery capstone marker as a second, native
-- SPELL_AURA_DUMMY effect (EFFECT_1, icon 119 - reusing the talent's own icon like Frost Warding's
-- capstone did with 501), read live by a new Unit::SpellPctDamageModsDone check (same commit):
-- "Increases the damage of your Frost spells against frozen targets by Mastery" - the first real
-- GetMasteryPercentage() consumer in this codebase.
--
-- Tooltip text updated to match ("direct Frost damage" instead of "Chill effects").

DELETE FROM `spell_dbc` WHERE `ID` IN (11071, 12496, 12497, 12494);
