INSERT INTO `spell_bonus_data` (`entry`, `direct_bonus`, `dot_bonus`, `ap_bonus`, `ap_dot_bonus`, `comments`) VALUES
(200014, 1.2, 0, 0, 0, 'Icy Shatter - Arctic Winds capstone, docs/frost-mage-redesign.md sec 4 Row 9 / sec 1 Glacial Spike');

-- Script bindings: Chilled to the Bone's new capstone script, Frostbite's proc-gate script (this
-- session's Frostbite pass added the class but never bound it - see header), and Biting Cold's
-- already-registered but never-bound capstone script (bug fix, see header).
DELETE FROM `spell_script_names` WHERE (`spell_id`, `ScriptName`) IN ((44568, 'spell_mage_chilled_to_the_bone'), (11071, 'spell_mage_frostbite'), (12496, 'spell_mage_frostbite'), (12497, 'spell_mage_frostbite'), (200012, 'spell_mage_biting_cold'));
