-- stacks on combat-leave, which let Icicles bank indefinitely for as long as combat lasted.
-- DurationIndex 9 is the stock client's existing 30000ms SpellDuration.dbc row, not a minted one -
-- apps/dbc-tools/lib/reuse.py's duration_index() finds it via find_or_mint() since a matching
-- Duration/MaxDuration pair already exists in the base client data, so no `spellduration_dbc`
-- overlay row is needed (that table stays empty for this ID, same as every other reused duration
-- in this rework). Hand-extracted from a full `generate.py` run rather than committing its output
-- wholesale - see docs/frost-mage-handoff.md's "every generate.py run reproduces a large,
-- pre-existing, unrelated diff" note. Source of truth: apps/dbc-tools/source/spells/mage.csv
-- (duration_ms 30000 on the Icicles row, id 200001). The `DurationIndex` = 21 guard makes this a
-- no-op on a second run.
UPDATE `spell_dbc` SET `DurationIndex` = 9 WHERE `ID` = 200001 AND `DurationIndex` = 21;

