-- ---------------------------------------------------------------
-- originally rev_1788207184589434880.sql
-- ---------------------------------------------------------------
-- Frost Mage rework - buff/debuff-bar tooltips ("no text" playtest report, 2026-08-31):
-- the client renders a buff/debuff icon's mouseover tooltip from `AuraDescription_Lang_enUS`,
-- not `Description_Lang_enUS` (the latter is what the spellbook/cast-bar tooltip uses). Six
-- rows in this session's new content set `Description_Lang_enUS` but never `AuraDescription_*`,
-- so their icon showed with no text even though the spell itself had a description - confirmed
-- against a working control (Refreshment, 200006, already had both fields and was never
-- reported broken) and against real Blizzard buff/debuff spells (Mage Armor, Ice Barrier, Slow,
-- Icy Veins, ...), which always populate AuraDescription for anything shown on a unit frame.
--
-- Per user direction, AuraDescription is set to the same text as the existing Description for
-- each: Icicles (200001), Shattering Cold (200003), Frozen Core's stacking Frost-damage buff
-- (200016/200017/200018), Frozen Core: Piercing Cold (200019), and Empowering Frostbolt
-- (200023/200024). Source of truth: apps/dbc-tools/source/spells/mage.csv and mage_talents.csv.
-- The `AuraDescription_Lang_enUS IS NULL` guard makes this a no-op on a second run.
UPDATE `spell_dbc` SET `AuraDescription_Lang_Mask` = 16712188, `AuraDescription_Lang_enUS` = 'Frost energy has gathered around you. Stacks up to 5 times; consumed by Glacial Spike.' WHERE `ID` = 200001 AND `AuraDescription_Lang_enUS` IS NULL;
UPDATE `spell_dbc` SET `AuraDescription_Lang_Mask` = 16712188, `AuraDescription_Lang_enUS` = 'This target''s frozen state is being exploited by the caster''s spells and abilities.' WHERE `ID` = 200003 AND `AuraDescription_Lang_enUS` IS NULL;
UPDATE `spell_dbc` SET `AuraDescription_Lang_Mask` = 16712188, `AuraDescription_Lang_enUS` = 'Increases Frost damage dealt by 2%.' WHERE `ID` = 200016 AND `AuraDescription_Lang_enUS` IS NULL;
UPDATE `spell_dbc` SET `AuraDescription_Lang_Mask` = 16712188, `AuraDescription_Lang_enUS` = 'Increases Frost damage dealt by 4%.' WHERE `ID` = 200017 AND `AuraDescription_Lang_enUS` IS NULL;
UPDATE `spell_dbc` SET `AuraDescription_Lang_Mask` = 16712188, `AuraDescription_Lang_enUS` = 'Increases Frost damage dealt by 6%.' WHERE `ID` = 200018 AND `AuraDescription_Lang_enUS` IS NULL;
UPDATE `spell_dbc` SET `AuraDescription_Lang_Mask` = 16712188, `AuraDescription_Lang_enUS` = 'Frost damage over time, pierced into the target''s core.' WHERE `ID` = 200019 AND `AuraDescription_Lang_enUS` IS NULL;
UPDATE `spell_dbc` SET `AuraDescription_Lang_Mask` = 16712188, `AuraDescription_Lang_enUS` = 'Increases critical strike damage bonus and Frost damage dealt.' WHERE `ID` = 200023 AND `AuraDescription_Lang_enUS` IS NULL;
UPDATE `spell_dbc` SET `AuraDescription_Lang_Mask` = 16712188, `AuraDescription_Lang_enUS` = 'Increases critical strike damage bonus and Frost damage dealt.' WHERE `ID` = 200024 AND `AuraDescription_Lang_enUS` IS NULL;

-- ---------------------------------------------------------------
-- originally rev_1788213988328353855.sql
-- ---------------------------------------------------------------
-- Frozen Orb Pulse (200008, spell_mage.cpp) damage/threat/combat-log attribution fix, found via
-- live playtest (2026-08-31): the pulse was cast by the orb creature on itself
-- (TARGET_UNIT_SRC_AREA_ENEMY resolves relative to the caster), so every hit was attributed to an
-- unnamed creature instead of the owning player - Fingers of Frost procced and the pulse showed
-- in the combat log, but never in the player's own damage meter. Fixed on the C++ side
-- (spell_mage.cpp: npc_mage_frozen_orb now has the owning player cast 200008 directly, once per
-- second, at an explicit dest = the orb's live position) which requires both of 200008's effects
-- to use a DEST-based area target instead of SRC, since SRC always resolves relative to whoever
-- is actually casting. TARGET_UNIT_DEST_AREA_ENEMY (16) keeps the AoE centered on the orb's
-- moving position while letting the player be the real caster (also fixes spell-power scaling,
-- which was previously reading off the orb's own nonexistent spell power instead of the player's).
UPDATE `spell_dbc` SET `ImplicitTargetA_1` = 16 WHERE `ID` = 200008 AND `ImplicitTargetA_1` = 15;
UPDATE `spell_dbc` SET `ImplicitTargetA_2` = 16 WHERE `ID` = 200008 AND `ImplicitTargetA_2` = 15;

-- ---------------------------------------------------------------
-- originally rev_1788214002505546169.sql
-- ---------------------------------------------------------------
-- Frozen Orb's projectile (300001, npc_mage_frozen_orb - spell_mage.cpp) reverted from the custom
-- "Ice Nuke Missile" display (90001, rev_1788159587319318946.sql) back to Ulduar's "Charged
-- Sphere" (26753, rev_1787850093039268564.sql). The custom model's own DBC row and client-side
-- patch (patch-M.mpq) were confirmed byte-for-byte correct and confirmed delivered to the tester's
-- client (matching size/mtime), but the model still rendered as invisible after a full client
-- restart - pointing at the underlying spells\IceNuke_Missile.mdx asset itself not being present
-- in this project's client build (a custom "Ascension" 3.3.5a client, not verified against a stock
-- reference copy for this specific asset). 26753 is a real, already-in-use stock CreatureDisplayID
-- (also used by npcs 33138/33756/33715) that was previously confirmed working in-game by the same
-- tester, so it's the safer known-good fallback pending an actual look at what spell-effect models
-- this client build actually ships.
UPDATE `creature_template_model` SET `CreatureDisplayID` = 26753 WHERE `CreatureID` = 300001 AND `CreatureDisplayID` = 90001;

-- ---------------------------------------------------------------
-- originally rev_1788222800752242616.sql
-- ---------------------------------------------------------------
-- Frozen Orb's projectile (300001, npc_mage_frozen_orb - spell_mage.cpp) was flagged
-- CREATURE_FLAG_EXTRA_TRIGGER (128, part of flags_extra = 194 = TRIGGER|NO_XP_AT_KILL|CIVILIAN) -
-- this is the actual root cause of the "model never renders for regular players" bug chased across
-- this session (ruled out: display ID 26753 vs 90001, and UNIT_FLAG_PLAYER_CONTROLLED, both
-- confirmed via live ablation testing to make no difference).
--
-- Unit::BuildValuesUpdateForPlayerWithFlag (Unit.cpp, UNIT_FIELD_DISPLAYID handling) special-cases
-- any creature with CREATURE_FLAG_EXTRA_TRIGGER: for every non-GM observer it force-overrides the
-- sent display ID to CreatureTemplate::GetFirstInvisibleModel() - which, since none of the orb's
-- creature_template_model rows are themselves marked is_trigger in creaturemodelinfo, falls through
-- to CreatureModel::DefaultInvisibleModel (the invisible stalker model), completely ignoring
-- whatever creature_template_model actually says. This is by design - CREATURE_FLAG_EXTRA_TRIGGER
-- marks a creature as a pure spell-effect helper NPC that's *supposed* to always be invisible to
-- real players (only a GM account sees the real model, for debugging) - it was never appropriate
-- for Frozen Orb's projectile, which needs to be visible to everyone. Clearing just that bit
-- (194 -> 66, keeping NO_XP_AT_KILL and CIVILIAN) lets the real creature_template_model display
-- (26753, "Charged Sphere") reach normal clients.
UPDATE `creature_template` SET `flags_extra` = 66 WHERE `entry` = 300001 AND `flags_extra` = 194;

-- ---------------------------------------------------------------
-- originally rev_1788232353595592675.sql
-- ---------------------------------------------------------------
-- Frozen Orb's projectile (300001, npc_mage_frozen_orb - spell_mage.cpp) switched back to the
-- real "Ice Nuke Missile" display (90001, Spells\IceNuke_Missile.mdx) from the stock "Charged
-- Sphere" fallback (26753, rev_1788214002505546169.sql). The 90001 swap was previously blamed and
-- reverted after live playtest found the orb invisible - that was a false lead: the real cause was
-- creature_template.flags_extra's CREATURE_FLAG_EXTRA_TRIGGER bit forcing an invisible model for
-- every non-GM client regardless of display ID (fixed in rev_1788222800752242616.sql; see
-- docs/bugs-and-fixes.md). With that fixed and confirmed live (Charged Sphere now renders
-- correctly), switching back to the intended Ice Nuke Missile model.
--
-- The creaturemodeldata_dbc/creaturedisplayinfo_dbc rows for ID 90001 already exist server-side
-- from that earlier attempt (never reverted, only the creature_template_model pointer was) - only
-- the pointer needs updating here. The client-side patch-M.mpq DBC patch was regenerated and
-- redeployed separately (apps/dbc-tools/patch_frozen_orb_model.py + build_patch_m.py), since the
-- working-copy DBCs at apps/dbc-tools/var/model-visual-dbc/DBFilesClient/ were rebuilt from a
-- clean client extraction during this session's AscensionFiles dependency removal and had lost
-- the 90001 rows.
UPDATE `creature_template_model` SET `CreatureDisplayID` = 90001 WHERE `CreatureID` = 300001 AND `CreatureDisplayID` = 26753;

-- ---------------------------------------------------------------
-- originally rev_1788235070301115912.sql
-- ---------------------------------------------------------------
-- Fingers of Frost (74396) charge consumption: playtest bugfix. The stock spell_proc row's
-- SchoolMask was 84 (Fire|Frost|Arcane), inherited unchanged from the pre-rework live data -
-- that let a plain Fire spell like Fireball (pure school 4, no Frost component) consume a charge,
-- since SchoolMask matching only requires overlap. docs/frost-mage-redesign.md never intended
-- Fingers of Frost to be spent by non-Frost damage, so this restricts SchoolMask to Frost (16)
-- alone. Frostfire Bolt (school 20 = Fire|Frost) still matches since 20 & 16 != 0.
DELETE FROM `spell_proc` WHERE `SpellId` = 74396;
